import math
def control(o):
    m=o['local_map']
    def at(points, x):
        p=sorted(points)
        for a,b in zip(p,p[1:]):
            if a[0]<=x<=b[0] and b[0]-a[0]>0.01:
                return a[1]+(b[1]-a[1])*(x-a[0])/(b[0]-a[0])
        return min(p,key=lambda z:abs(z[0]-x))[1]
    l=m['left_rail']; r=m['right_rail']
    c=(at(l,5.0)+at(r,5.0))/2
    h=o['hitch_deg']
    target=max(-14,min(14,c*4.0))
    steer=max(-35,min(35,2.0*(h-target)))
    return (steer,-0.8,180)

